import * as React from "react";
import { cx } from "./cx";

export interface CollapsibleProps
  extends Omit<React.DetailsHTMLAttributes<HTMLDetailsElement>, "title"> {
  title: React.ReactNode;
  defaultOpen?: boolean;
}

/** A bare native <details>. */
export function Collapsible({ title, defaultOpen, className, children, ...props }: CollapsibleProps) {
  return (
    <details className={cx("rs-disclosure", className)} open={defaultOpen || undefined} {...props}>
      <summary>
        {title}
        <svg className="rs-acc-chevron" viewBox="0 0 16 16" width="14" height="14" fill="none" aria-hidden="true">
          <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </summary>
      <div className="rs-disclosure-body">{children}</div>
    </details>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Collapsible: a bare <details>, no chrome ── */
.rs-disclosure summary{list-style:none;cursor:pointer;display:inline-flex;align-items:center;gap:7px;font-size:13.5px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-disclosure summary::-webkit-details-marker{display:none}
.rs-disclosure .rs-acc-chevron{transition:transform .2s ease}
.rs-disclosure[open] .rs-acc-chevron{transform:rotate(180deg)}
.rs-disclosure-body{padding:10px 0 0;font-size:13.5px;line-height:1.6;color:var(--text-secondary)}
